#pragma once

#include <string>
#include <string_view>
#include <unordered_map>
#include <vector>
#include <optional>
#include <algorithm>
#include <cstdint>
#include <nlohmann/json.hpp>

namespace ptv_haptics {

// Hand selector used by the tag protocol
enum class Hand : std::uint8_t { Left=0, Right=1, Both=2 };

inline std::string_view to_string(Hand h) {
    switch (h) {
        case Hand::Left: return "left";
        case Hand::Right: return "right";
        case Hand::Both: return "both";
    }
    return "right";
}

inline std::optional<Hand> parse_hand(std::string_view s) {
    if (s == "left") return Hand::Left;
    if (s == "right") return Hand::Right;
    if (s == "both") return Hand::Both;
    return std::nullopt;
}

// Known pattern ids (string keys used in the publish protocol)
// hover_light, bolt_fire_sharp, construct_form_heavy, recharge_rhythm,
// block_impact_strong, sprint_start, sprint_end, flight_boost, evade_burst

struct PatternDef {
    float base_amp{0.6f};        // 0..1 baseline amplitude
    float default_duration_s{0.08f};
    // Optional attack/decay shaping hint (0..1). Not used by engine directly, kept for future expansion.
    float attack_s{0.005f};
    float decay_s{0.03f};
};

struct PublishReq {
    std::string pattern_id;            // required
    Hand hand{Hand::Right};            // default right
    float intensity_scale{1.0f};       // additional scalar from caller (e.g., construct weight)
    std::optional<float> duration_s;   // optional override
};

// Tag protocol (cross-mechanic, string-only, no shared headers needed):
//   To publish (from any entity): add a CTag entry string starting with
//     "haptics.publish:{json}"
//   JSON shape: { "pattern_id":"bolt_fire_sharp", "hand":"right|left|both",
//                 "intensity_scale":1.0, "duration_s":0.12 }
//   The manager consumes and removes that tag, then emits on its own attached entity
//     "haptics.play:{json}"
//   JSON shape: { "pattern":"bolt_fire_sharp", "hand":"right",
//                 "amp":0.85, "dur_s":0.12 }

inline constexpr std::string_view kPublishPrefix = "haptics.publish:";
inline constexpr std::string_view kPlayPrefix    = "haptics.play:";

// Safe parse of a publish JSON blob into PublishReq
inline std::optional<PublishReq> parse_publish_json(const std::string& json_text) {
    auto j = nlohmann::json::parse(json_text, nullptr, /*allow_exceptions=*/false);
    if (!j.is_object()) return std::nullopt;
    PublishReq r{};
    if (!j.contains("pattern_id")) return std::nullopt;
    r.pattern_id = j.value("pattern_id", std::string{});
    auto h_str = j.value("hand", std::string("right"));
    if (auto h = parse_hand(h_str)) r.hand = *h; else r.hand = Hand::Right;
    r.intensity_scale = j.value("intensity_scale", 1.0f);
    if (j.contains("duration_s")) r.duration_s = j.value("duration_s", 0.0f);
    return r;
}

// Compose a play tag JSON payload
inline std::string make_play_json(const std::string& pattern, Hand hand, float amp, float dur_s) {
    nlohmann::json j;
    j["pattern"] = pattern;
    j["hand"] = std::string(to_string(hand));
    j["amp"] = amp;
    j["dur_s"] = dur_s;
    return j.dump();
}

// Clamp helper
inline float clamp01(float v) { return std::max(0.0f, std::min(1.0f, v)); }

// Lightweight ring buffer for recent events (debug/validation)
struct RecentEvents {
    struct Item { std::string pattern; std::string hand; float amp; float dur; };
    std::vector<Item> items;
    std::size_t max_items{32};
    void push(Item i) {
        items.emplace_back(std::move(i));
        if (items.size() > max_items) items.erase(items.begin());
    }
};

} // namespace ptv_haptics

#include "haptics_shared.h"

#include <unordered_map>
#include <string>

namespace ptv_haptics {

static std::unordered_map<std::string, PatternDef> build_default_patterns() {
    // Tuned intuitively for VR controllers; amplitudes are relative and will be
    // multiplied by user/global/caller scales.
    std::unordered_map<std::string, PatternDef> m;
    m["hover_light"]             = PatternDef{0.25f, 0.040f, 0.002f, 0.020f};
    m["bolt_fire_sharp"]        = PatternDef{0.85f, 0.055f, 0.001f, 0.030f};
    m["construct_form_heavy"]   = PatternDef{1.00f, 0.120f, 0.004f, 0.060f};
    m["recharge_rhythm"]        = PatternDef{0.35f, 0.300f, 0.010f, 0.120f}; // single beat; callers can re-publish to sustain
    m["block_impact_strong"]    = PatternDef{0.95f, 0.090f, 0.002f, 0.050f};
    m["sprint_start"]           = PatternDef{0.70f, 0.080f, 0.003f, 0.040f};
    m["sprint_end"]             = PatternDef{0.55f, 0.070f, 0.003f, 0.035f};
    m["flight_boost"]           = PatternDef{0.80f, 0.100f, 0.004f, 0.050f};
    m["evade_burst"]            = PatternDef{0.90f, 0.070f, 0.002f, 0.030f};
    return m;
}

// Accessor for a single static instance
const std::unordered_map<std::string, PatternDef>& pattern_map() {
    static std::unordered_map<std::string, PatternDef> k = build_default_patterns();
    return k;
}

} // namespace ptv_haptics

#include "ptv/ecs/World.h"
#include <entt/entt.hpp>
#include <string>
#include <vector>
#include <cstdint>
#include <algorithm>

#include "haptics_shared.h"

namespace ptv_haptics {

// Compute final amplitude and duration for a request
inline void resolve_play_params(const PublishReq& req,
                                float user_intensity_scale,
                                const std::unordered_map<std::string, PatternDef>& defs,
                                float& out_amp,
                                float& out_dur_s) {
    auto it = defs.find(req.pattern_id);
    const PatternDef* def = (it != defs.end()) ? &it->second : nullptr;
    const float base_amp = def ? def->base_amp : 0.6f;
    const float base_dur = def ? def->default_duration_s : 0.08f;
    out_dur_s = req.duration_s.has_value() ? std::max(0.01f, *req.duration_s) : base_dur;
    out_amp = ptv_haptics::clamp01(base_amp * req.intensity_scale * user_intensity_scale);
}

// Consume one publish tag string. Returns true if consumed.
bool try_consume_publish_tag(const std::string& tag_str, PublishReq& out) {
    using namespace ptv_haptics;
    if (tag_str.rfind(std::string(kPublishPrefix), 0) != 0) return false; // no prefix
    const std::string json_part = tag_str.substr(std::string(kPublishPrefix).size());
    auto parsed = parse_publish_json(json_part);
    if (!parsed) return false;
    out = *parsed;
    return true;
}

// Emit one or two play tags onto the target entity's CTag
void emit_play_tags(ptv::World& w, std::uint32_t target_entity,
                    const std::string& pattern, ptv_haptics::Hand hand,
                    float amp, float dur_s, ptv_haptics::RecentEvents& recent) {
    using namespace ptv_haptics;
    if (!w.has<ptv::CTag>(target_entity)) {
        w.emplace_or_replace<ptv::CTag>(target_entity, ptv::CTag{});
    }
    auto& tag = w.get<ptv::CTag>(target_entity);

    auto push = [&](Hand h){
        std::string payload = std::string(kPlayPrefix) + make_play_json(pattern, h, amp, dur_s);
        tag.tags.emplace_back(std::move(payload));
        recent.push({pattern, std::string(to_string(h)), amp, dur_s});
    };

    if (hand == Hand::Both) {
        push(Hand::Left);
        push(Hand::Right);
    } else {
        push(hand);
    }
}

} // namespace ptv_haptics

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <entt/entt.hpp>
#include <nlohmann/json.hpp>
#include <string>
#include <vector>
#include <utility>
#include <cstdint>
#include <algorithm>

#include "haptics_shared.h"

// Forward decl from patterns unit
namespace ptv_haptics { const std::unordered_map<std::string, PatternDef>& pattern_map(); }

// Service helpers
namespace ptv_haptics {
    bool try_consume_publish_tag(const std::string& tag_str, PublishReq& out);
    void emit_play_tags(ptv::World& w, std::uint32_t target_entity,
                        const std::string& pattern, Hand hand,
                        float amp, float dur_s, RecentEvents& recent);
}

namespace ptv {

class HapticsManager final : public IMechanic {
public:
    void on_attach(World& world, std::uint32_t entity, const nlohmann::json& params) override {
        self_ = entity;
        // Global/user intensity scale (fallback until Accessibility Settings task exists)
        user_intensity_ = params.value("default_intensity", 1.0f);
        user_intensity_ = std::clamp(user_intensity_, 0.0f, 2.0f);
        // Optional debug: keep more recent events
        recent_.max_items = static_cast<std::size_t>(std::clamp(params.value("recent_events", 32), 1, 256));
    }

    void on_update(World& world, std::uint32_t /*entity*/, float /*dt*/) override {
        // Scan all entities for publish tags, consume, and emit resolved play tags onto self_
        auto& defs = ptv_haptics::pattern_map();
        auto& reg = world.registry();
        auto view = reg.view<CTag>();
        for (auto e : view) {
            std::uint32_t ent = static_cast<std::uint32_t>(e);
            auto& ctag = view.get<CTag>(e);
            if (ctag.tags.empty()) continue;

            // Walk and collect indices to erase after processing to avoid iterator invalidation
            std::vector<std::size_t> to_erase;
            for (std::size_t i = 0; i < ctag.tags.size(); ++i) {
                const std::string& t = ctag.tags[i];
                ptv_haptics::PublishReq req;
                if (!ptv_haptics::try_consume_publish_tag(t, req)) continue;

                // Resolve parameters
                float amp = 0.6f, dur = 0.08f;
                ptv_haptics::resolve_play_params(req, user_intensity_, defs, amp, dur);

                // Emit onto manager's entity so device/plugin can read a single place
                if (world.valid(self_)) {
                    ptv_haptics::emit_play_tags(world, self_, req.pattern_id, req.hand, amp, dur, recent_);
                }

                to_erase.push_back(i);
            }
            if (!to_erase.empty()) {
                // Erase from back to front
                std::sort(to_erase.begin(), to_erase.end());
                for (std::size_t k = 0; k < to_erase.size(); ++k) {
                    std::size_t idx = to_erase[to_erase.size() - 1 - k];
                    if (idx < ctag.tags.size()) ctag.tags.erase(ctag.tags.begin() + static_cast<std::ptrdiff_t>(idx));
                }
            }
        }

        // Optional: self-test hook to guarantee pattern presence for acceptance
        // Add a one-time map-export tag listing supported patterns if asked via params flag
        if (!announced_patterns_ && announce_supported_) {
            announced_patterns_ = true;
            if (!world.has<CTag>(self_)) world.emplace_or_replace<CTag>(self_, CTag{});
            auto& t = world.get<CTag>(self_);
            nlohmann::json j;
            j["patterns"] = nlohmann::json::array();
            for (const auto& kv : ptv_haptics::pattern_map()) j["patterns"].push_back(kv.first);
            t.tags.emplace_back(std::string(ptv_haptics::kPlayPrefix) + j.dump());
        }
    }

    void on_detach(World& world, std::uint32_t entity) override {
        // Best-effort: drop any lingering play announcements on detach
        if (world.has<CTag>(entity)) {
            auto& t = world.get<CTag>(entity);
            auto& vec = t.tags;
            vec.erase(std::remove_if(vec.begin(), vec.end(), [](const std::string& s){
                return s.rfind(std::string(ptv_haptics::kPlayPrefix), 0) == 0;
            }), vec.end());
        }
    }

    std::string id() const override { return "generated.haptics_manager"; }

private:
    std::uint32_t self_{0};
    float user_intensity_{1.0f};
    ptv_haptics::RecentEvents recent_{};
    bool announce_supported_{true};
    bool announced_patterns_{false};
};

} // namespace ptv

PTV_REGISTER_MECHANIC("generated.haptics_manager", ptv::HapticsManager)
